package com.nm.fragmentsclean.adminImportContext.adapters.primary.rest;
import com.nm.fragmentsclean.adminImportContext.businessLogic.usecases.*; import com.nm.fragmentsclean.adminImportContext.businessLogic.ports.TopicCandidateStudioCatalog; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/admin/editorial/topic-candidates") public final class AdminTopicCandidatesController {private final DecideStudioTopicCandidate decisions;private final TopicCandidateStudioCatalog candidates;private final StartArticleGenerationFromTopicCandidate authoring;public AdminTopicCandidatesController(DecideStudioTopicCandidate decisions,TopicCandidateStudioCatalog candidates,StartArticleGenerationFromTopicCandidate authoring){this.decisions=decisions;this.candidates=candidates;this.authoring=authoring;}@GetMapping public java.util.List<TopicCandidateStudioCatalog.Item> list(){return candidates.list();}@PostMapping("/{id}/{decision:retain|defer|ignore}") public ResponseEntity<Void> decide(@PathVariable UUID id,@PathVariable String decision){decisions.execute(id,decision.toUpperCase());return ResponseEntity.accepted().build();}@PostMapping("/{id}/start-authoring") public ResponseEntity<com.nm.fragmentsclean.adminImportContext.businessLogic.models.StudioArticleGenerationResult> start(@PathVariable UUID id,@RequestBody AuthoringRequest r,Authentication authentication){UUID operatorId=UUID.fromString(authentication.getName());return ResponseEntity.accepted().body(authoring.execute(id,r.locale(),operatorId,authentication.getName()));}public record AuthoringRequest(String locale){}}
